def solve(inputs: dict) -> float:
    a = int(inputs['A']) % int(inputs['MOD'])
    b = int(inputs['B']) % int(inputs['MOD'])
    c = int(inputs['C']) % int(inputs['MOD'])
    d = int(inputs['D']) % int(inputs['MOD'])
    mod = int(inputs['MOD'])
    k = int(inputs['K'])
    def matmul(x, y):
        return (
            ((x[0]*y[0] + x[1]*y[2]) % mod),
            ((x[0]*y[1] + x[1]*y[3]) % mod),
            ((x[2]*y[0] + x[3]*y[2]) % mod),
            ((x[2]*y[1] + x[3]*y[3]) % mod),
        )
    res = (1,0,0,1)
    base = (a,b,c,d)
    while k:
        if k & 1:
            res = matmul(res, base)
        base = matmul(base, base)
        k >>= 1
    return float(sum(res) % mod)

